'use strict';
/* Date-specific attendance sign-off records, one per active demo user account. */
let attendanceSignoffSelectedUser='';
function attendanceSignoffUsers(){return (db.users||[]).filter(u=>u.status!=='Inactive'&&(u.username||u.id))}
function attendanceSignoffMarkup(){
  const users=attendanceSignoffUsers();
  if(!attendanceSignoffSelectedUser||!users.some(u=>(u.username||u.id)===attendanceSignoffSelectedUser))attendanceSignoffSelectedUser=users[0]?.username||users[0]?.id||'';
  const records=db.attendanceSignoffs?.[attendanceSelectedDate]||{};
  const options=users.map(u=>{const key=u.username||u.id;return '<option value="'+esc(key)+'"'+(key===attendanceSignoffSelectedUser?' selected':'')+'>'+esc(u.name||key)+' ('+esc(key)+')</option>'}).join('');
  const signed=Object.entries(records).map(([key,r])=>'<div class="attendanceSignoffRecord"><strong>'+esc(r.name||key)+'</strong><span>'+esc(key)+'</span><time>'+esc(new Date(r.at).toLocaleString('en-IN'))+'</time></div>').join('')||'<small class="attendanceSignoffEmpty">No sign-off recorded for this date.</small>';
  return '<section class="attendanceSignoff"><div class="attendanceSignoffHead"><div><h3>Attendance Sign-off</h3><p>Each active user account can sign off once for this date.</p></div><span class="attendanceSignoffDate">'+esc(attendanceSelectedDate)+'</span></div><div class="attendanceSignoffControls"><label for="attendanceSignoffUser">Login account</label><select id="attendanceSignoffUser" '+(users.length?'':'disabled')+'>'+ (options||'<option value="">No active user accounts</option>')+'</select><button type="button" class="btn secondary" id="attendanceSignoffButton" '+(users.length?'':'disabled')+'>Sign Off Attendance</button></div><div class="attendanceSignoffNote">Demo sign-off only: choose the account recording approval. This prototype does not verify user login.</div><div class="attendanceSignoffRecords">'+signed+'</div></section>';
}
const attendanceDailyMarkupBeforeSignoff=dailyAttendanceMarkup;
dailyAttendanceMarkup=function(){const host=document.createElement('div');host.innerHTML=attendanceDailyMarkupBeforeSignoff();const view=host.querySelector('.attendanceView');if(view)view.insertAdjacentHTML('beforeend',attendanceSignoffMarkup());return host.innerHTML};
document.addEventListener('change',e=>{if(e.target.id==='attendanceSignoffUser')attendanceSignoffSelectedUser=e.target.value});
document.addEventListener('click',e=>{if(!e.target.closest('#attendanceSignoffButton'))return;const user=attendanceSignoffUsers().find(u=>(u.username||u.id)===attendanceSignoffSelectedUser);if(!user)return toast('Select an active user account first.');if($('.attendanceSaveState')?.classList.contains('unsaved'))return toast('Save attendance before signing off.');const date=attendanceSelectedDate,key=user.username||user.id;db.attendanceSignoffs=db.attendanceSignoffs||{};db.attendanceSignoffs[date]=db.attendanceSignoffs[date]||{};if(db.attendanceSignoffs[date][key])return toast('This account has already signed off for this date.');const before=structuredClone(db.attendanceSignoffs);db.attendanceSignoffs[date][key]={username:key,name:user.name||key,role:user.role||'',at:new Date().toISOString()};audit('Sign Off',`Attendance ${date} signed off by ${key}`);if(db.audit?.[0])db.audit[0].user=key;if(save('Attendance signed off')===false){db.attendanceSignoffs=before;if(db.audit?.[0]?.detail?.includes(`signed off by ${key}`))db.audit.shift();return}render()});
const attendanceSignoffStyle=document.createElement('style');attendanceSignoffStyle.textContent='.attendanceSignoff{margin-top:14px;padding:13px 15px;background:#fff;border:1px solid #dbe3ec}.attendanceSignoffHead{display:flex;align-items:center;justify-content:space-between;gap:10px}.attendanceSignoffHead h3{margin:0;color:#17283b;font-size:13px}.attendanceSignoffHead p{margin:4px 0 0;color:#718096;font-size:10px}.attendanceSignoffDate{padding:4px 8px;background:#f1f5f9;color:#475569;font-size:10px;font-weight:700}.attendanceSignoffControls{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:11px}.attendanceSignoffControls label{font-size:10px;font-weight:700;color:#475569}.attendanceSignoffControls select{width:auto;min-width:180px;min-height:31px;height:31px;padding:4px 8px;font-size:10px}.attendanceSignoffControls .btn{min-height:31px;padding:5px 10px;font-size:10px}.attendanceSignoffNote{margin-top:8px;color:#8793a3;font-size:9px}.attendanceSignoffRecords{display:flex;align-items:center;gap:7px;flex-wrap:wrap;margin-top:10px}.attendanceSignoffRecord{display:flex;align-items:center;gap:7px;padding:6px 8px;border:1px solid #bbf7d0;background:#f0fdf4;color:#166534;font-size:9px}.attendanceSignoffRecord span{color:#475569}.attendanceSignoffRecord time{color:#64748b}.attendanceSignoffEmpty{color:#718096;font-size:10px}@media(max-width:600px){.attendanceSignoff{padding:10px}.attendanceSignoffControls label{flex-basis:100%}.attendanceSignoffControls select,.attendanceSignoffControls button{flex:1 1 100%;width:100%}.attendanceSignoffRecord{flex-wrap:wrap}}';document.head.appendChild(attendanceSignoffStyle);